// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListRules The seven community rules (public)
	// (GET /rules)
	ListRules(ctx context.Context, request ListRulesRequestObject) (ListRulesResponseObject, error)
	// ListBlocklist Blocklist terms; the browser checks them while typing
	// (GET /screening/blocklist)
	ListBlocklist(ctx context.Context, request ListBlocklistRequestObject) (ListBlocklistResponseObject, error)
	// AddBlocklistTerm Add a term with the rule it belongs to
	// (POST /screening/blocklist)
	AddBlocklistTerm(ctx context.Context, request AddBlocklistTermRequestObject) (AddBlocklistTermResponseObject, error)
	// DeleteBlocklistTerm Remove a term
	// (DELETE /screening/blocklist/{term_id})
	DeleteBlocklistTerm(ctx context.Context, request DeleteBlocklistTermRequestObject) (DeleteBlocklistTermResponseObject, error)
	// SetChannelThreshold Set or clear a channel's hold threshold (null uses the global one)
	// (PUT /screening/channels/{channel_id}/threshold)
	SetChannelThreshold(ctx context.Context, request SetChannelThresholdRequestObject) (SetChannelThresholdResponseObject, error)
	// CheckDraft Check a draft before sending (FR-3.1). The draft is not stored and warnings never count as violations.
	// (POST /screening/check)
	CheckDraft(ctx context.Context, request CheckDraftRequestObject) (CheckDraftResponseObject, error)
	// GetScreeningSettings Thresholds, auto-delete, outage policy and per-channel thresholds
	// (GET /screening/settings)
	GetScreeningSettings(ctx context.Context, request GetScreeningSettingsRequestObject) (GetScreeningSettingsResponseObject, error)
	// UpdateScreeningSettings Change thresholds and the outage policy; applies without a restart
	// (PUT /screening/settings)
	UpdateScreeningSettings(ctx context.Context, request UpdateScreeningSettingsRequestObject) (UpdateScreeningSettingsResponseObject, error)
	// SetStandInOffline Simulate a model outage (stand-in scorer only), to try the outage policy
	// (PUT /screening/stand-in)
	SetStandInOffline(ctx context.Context, request SetStandInOfflineRequestObject) (SetStandInOfflineResponseObject, error)
	// GetScreeningStatus Whether the model answers, so the composer can say checks are delayed
	// (GET /screening/status)
	GetScreeningStatus(ctx context.Context, request GetScreeningStatusRequestObject) (GetScreeningStatusResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

